# -----------------------------------------------------------------------------
# Dynamic AutoCAD plot-log reference
# -----------------------------------------------------------------------------
# No paper size or scale is hardcoded.  When an AutoCAD plot/publish log is
# found, the FIRST complete DWG plot row is used as the batch reference and its
# plotter/paper/scale values are force-applied to every later DWG/layout.
# If no plot log is found, the script does not invent values; it falls back to
# each drawing layout setup.

def _install_absolute_reference_record(settings: dict, log: Callable[[str, str], None]) -> Optional[dict]:
    """Backward-compatible no-op.

    Older debug builds called this to install hardcoded A0 / 1:1 settings.
    That is intentionally disabled: reference settings must come from the first
    detected AutoCAD plot-log row, not from fixed values.
    """
    rec = settings.get("plot_log_map", {}).get("__batch_default__", {}).get("__default__")
    if rec:
        settings["_absolute_first_plot_log_record"] = rec
        bits = []
        if rec.get("plotter"):
            bits.append(f"plotter={rec.get('plotter')}")
        if rec.get("paper"):
            bits.append(f"paper={rec.get('paper')}")
        if rec.get("scale"):
            bits.append(f"scale={rec.get('scale')}")
        log("Using FIRST detected AutoCAD plot-log row as dynamic batch reference: " + ", ".join(bits), "ok")
        return rec
    settings.pop("_absolute_first_plot_log_record", None)
    log("No plot-log reference row found. No paper/scale values will be forced; using drawing page setups.", "warn")
    return None


