def _branding_cache_dir() -> Path:
    base = Path(os.environ.get("LOCALAPPDATA", tempfile.gettempdir())) / "CADPlotCenter"
    base.mkdir(parents=True, exist_ok=True)
    return base


def _write_embedded_asset(filename: str, b64_data: str) -> Path:
    path = _branding_cache_dir() / filename
    data = __import__("base64").b64decode("".join(b64_data.split()))
    try:
        if not path.exists() or path.stat().st_size != len(data):
            path.write_bytes(data)
    except Exception:
        # Fallback to temp if LOCALAPPDATA is locked down.
        path = Path(tempfile.gettempdir()) / filename
        if not path.exists() or path.stat().st_size != len(data):
            path.write_bytes(data)
    return path


def get_icon_path() -> Path:
    return _write_embedded_asset("cad_plot_center.ico", _ICON_B64)


def get_logo_path() -> Path:
    return _write_embedded_asset("cad_plot_center_logo.png", _LOGO_B64)

